<script>
	import QiscusTriggerBtn from './components/qiscus-trigger-btn.svelte';
	import LoginForm from './components/login-form.svelte';
	import { onMount } from 'svelte';
	import { 
		_ajax, generateDefaultConfig, 
		setDefaultConfig, attachQismoCustomCSS,
		fadeIn, fadeOut
	} from './helper.js';
	/*
	What's need to be done:
	- Load Qismo config from api
	- Render trigger button based on qismo config
	- Render Welcome message if any
	- Render Attention Grabber if any
	*/

	let isInitiated = false;
	let isLogin = false;
	let defaultConfig = {};
	let isLoginFormOpened = false;
	let isWidgetOpened = false;
	let isMobile = false;
	let userData;
	let loginFormIframe;
	let welcomeMessageIframe;
	let attentionGrabberIframe;
	let widgetIframe;
	let customcss;
	export let widgetDesktopSizes = [300, 450];
	export let loginFormSizes = [360, 510];
	export let welcomeMessageSizes = [360,200];
	export let grabberSizes = [300,150];

	const loadQismo = () => {
		defaultConfig = generateDefaultConfig();
		_ajax({
            type: 'GET',
            url: defaultConfig.qismoBaseUrl+'/api/v1/app/config/public-widget/'+appId,
            successFn: function(res) {
                var data = res.data.widget;
                setDefaultConfig(data, options);
				customcss = attachQismoCustomCSS(data ? data.styles : null);
				renderWelcomeMessage();
				renderAttentionGrabber();
				renderLoginForm();
				isInitiated = true;
				if(localStorage.getItem('qismo-data')) login();
            },
            failFn: function(err) {},
        });
	}
	const renderAttentionGrabber = () => {
		if(qismoConfig.attentionGrabberStatus != true) return false;
		welcomeMessageIframe = document.createElement('iframe');
		let width = 300;
		let height = 150;
		let iframeSource = qismoConfig.qismoIframeUrl+'/iframes/attention-grabber?grabberImage='+qismoConfig.grabberImage+'&grabberTextStatus='+qismoConfig.grabberTextStatus+'&attention_grabber_image='+qismoConfig.attentionGrabberImage+'&attention_grabber_text='+qismoConfig.attentionGrabberText;
		welcomeMessageIframe.setAttribute('src', iframeSource);
		welcomeMessageIframe.setAttribute('id', 'qcw-welcome-iframe');
		changeIframeSize(welcomeMessageIframe, grabberSizes[0]+'px', grabberSizes[1]+'px', '0');
		if(!document.getElementById('qcw-welcome-iframe')) document.body.appendChild(welcomeMessageIframe);
		fadeIn(welcomeMessageIframe);
	}
	const renderWelcomeMessage = () => {
		const ls = localStorage.getItem('qismo-data');
		if(qismoConfig.welcomeMessageStatus != true || qismoConfig.attentionGrabberStatus == true || ls) return false;
		var timeout = qismoConfig.welcomeTimeout >=0 ? qismoConfig.welcomeTimeout : defaultConfig.welcomeTimeout;
		setTimeout(function() {
			welcomeMessageIframe = document.createElement('iframe');
			let iframeSource = qismoConfig.qismoIframeUrl+'/iframes/welcome-message?avatar_url='+qismoConfig.customerServiceAvatar+'&cs_name='+qismoConfig.customerServiceName+'&welcome_text='+qismoConfig.welcomeText;
			welcomeMessageIframe.setAttribute('src', iframeSource);
			welcomeMessageIframe.setAttribute('id', 'qcw-welcome-iframe');
			welcomeMessageIframe.style.display = 'none';
			changeIframeSize(welcomeMessageIframe, welcomeMessageSizes[0]+'px', welcomeMessageSizes[1]+'px', '0');
			if(!document.getElementById('qcw-welcome-iframe')) document.body.appendChild(welcomeMessageIframe);
			if(!isLoginFormOpened && !isWidgetOpened) {
				welcomeMessageIframe.style.display = 'block';
				fadeIn(welcomeMessageIframe, () => {
					setTimeout(() => {
						sendMessage('qcw-welcome-iframe', { event_name: 'custom-css', css: customcss })
					}, 1000);
				});
			}
        }, parseInt(timeout)*1000)
	}
	export const toggleLoginForm = () => {
		if(isLogin) return false;
		isLoginFormOpened = !isLoginFormOpened
		const el = document.getElementById('qcw-login-form-iframe');
		if(!el) return false;
		if(isLoginFormOpened) {
			fadeIn(el, () => {
				setTimeout(() => {
					if(qismoConfig.loginFormCustomCSS) sendMessage('qcw-login-form-iframe', { event_name: 'custom-css', css: qismoConfig.loginFormCustomCSS })
					if(customcss) sendMessage('qcw-login-form-iframe', { event_name: 'custom-css-api', css: customcss })
				}, 0);
			});
			closeWelcomeMessage();
		} else {
			fadeOut(el);
		}
	}
	export const toggleWidget = () => {
		if(isLogin) {
			isWidgetOpened = !isWidgetOpened;
			toggleQiscusWidget();
		} else {
			toggleLoginForm();
		}
		if(isWidgetOpened || isLoginFormOpened) closeWelcomeMessage();
	}
	export const login = (data) => {
		let ls = JSON.parse(localStorage.getItem('qismo-data'));
		const isLoginFromForm = !ls ? true : false;
		if(ls) {
			userData = {
				display_name: ls.display_name,
				unique_id: ls.unique_id,
			}
		} else {
			userData = data;
			localStorage.setItem('qismo-data', JSON.stringify(userData));
		}
		
		renderQiscusWidget(isLoginFromForm);
		isLogin = true;
		isLoginFormOpened = false;
		fadeOut(loginFormIframe);
	}
	const toggleQiscusWidget = () => {
		const el = document.getElementById('qcw-iframe');
		if(!el) return false;
		if(isWidgetOpened) {
			fadeIn(el, () => {
				if(!qismoConfig.widgetCustomCSS) return false;
				setTimeout(() => {
					sendMessage('qcw-iframe', { event_name: 'custom-css', css: qismoConfig.widgetCustomCSS })
				}, 1000);
			});
			closeWelcomeMessage();
		} else {
			fadeOut(el);
		}
	}
	export const closeWelcomeMessage = () => {
		const el = document.getElementById('qcw-welcome-iframe');
		if(el) fadeOut(el);
	}
	var sendMessage = function(el, msg) {
		// Make sure you are sending a string, and to stringify JSON
		document.getElementById(el).contentWindow.postMessage(msg, '*');
	};
	const renderLoginForm = () => {
		loginFormIframe = document.createElement('iframe');
		const customerIdentifier = qismoConfig.customerIdentifier ? qismoConfig.customerIdentifier : qismoConfig.customerIdentifierInputType;
		let iframeSource = qismoConfig.qismoIframeUrl+'/iframes/login-form?formGreet='+qismoConfig.formGreet+'&customerIdentifier='+customerIdentifier;
        loginFormIframe.setAttribute('src', iframeSource);
		loginFormIframe.setAttribute('id', 'qcw-login-form-iframe');
		if(document.body.clientWidth < 600) {
			changeMobileIframeSize(loginFormIframe);
		} else {
			changeIframeSize(loginFormIframe, loginFormSizes[0]+'px', loginFormSizes[1]+'px');
		}
		if(!document.getElementById('qcw-login-form-iframe')) document.body.appendChild(loginFormIframe);
		if(qismoConfig.openAtStart) {
			isLoginFormOpened = true;
			fadeIn(loginFormIframe, () => {
				if(qismoConfig.loginFormCustomCSS) sendMessage('qcw-login-form-iframe', { event_name: 'custom-css', css: qismoConfig.loginFormCustomCSS })
				if(customcss) sendMessage('qcw-login-form-iframe', { event_name: 'custom-css-api', css: customcss })
			});
		}  else {
			fadeOut(loginFormIframe);
		}
	}

	const renderQiscusWidget = (isLoginFromForm) => {
		widgetIframe = document.createElement('iframe');
		let iframeSource = qismoConfig.qismoIframeUrl+'/multichannel-widget?display_name='+userData.display_name+'&unique_id='+userData.unique_id+'&app_id='+appId;
        widgetIframe.setAttribute('src', iframeSource);
		widgetIframe.setAttribute('id', 'qcw-iframe');
		widgetIframe.setAttribute('style', 'display: none');
		if(document.body.clientWidth < 600) {
			changeMobileIframeSize(widgetIframe);
		} else {
			changeIframeSize(widgetIframe, widgetDesktopSizes[0]+'px', widgetDesktopSizes[1]+'px');
		}
		if(!document.getElementById('qcw-iframe')) document.body.appendChild(widgetIframe);

		if(qismoConfig.openAtStart || isLoginFromForm) {
			isWidgetOpened = true;
			fadeIn(widgetIframe, () => {
				if(!qismoConfig.widgetCustomCSS) return false;
				setTimeout(() => {
					sendMessage('qcw-iframe', { event_name: 'custom-css', css: qismoConfig.widgetCustomCSS })
				}, 1000);
			});
		}
	};

	const changeIframeSize = (el, width, height, x, y) => {
		if(!el) return false;
		el.style.width = width;
		el.style.height = height;
		el.style.bottom = y ? y : '87px';
		el.style.right = x ? x : '42px';
	}
	const changeMobileIframeSize = (el) => {
		changeIframeSize(el, '100%', '100%');
		el.style.bottom = 0;
		el.style.right = 0;
	}

	const setMobileView = () => {
		if(document.body.clientWidth < 600) {
			isMobile = true;
			if(widgetIframe) changeMobileIframeSize(widgetIframe);
			if(loginFormIframe) changeMobileIframeSize(loginFormIframe);
		} else {
			isMobile = false;
			if(widgetIframe) changeIframeSize(widgetIframe, widgetDesktopSizes[0]+'px', widgetDesktopSizes[1]+'px');
			if(loginFormIframe) changeIframeSize(loginFormIframe, loginFormSizes[0]+'px', loginFormSizes[1]+'px');
		}
	}
	onMount(async () => {
		loadQismo();
		window.addEventListener("resize", function(event) {
			setMobileView();
		})

		setMobileView();

		return () => {
			if(widgetIframe && typeof widgetIframe == 'object') {
				document.body.removeChild(widgetIframe);
				widgetIframe = null;
			}
			if(loginFormIframe && typeof loginFormIframe == 'object') {
				document.body.removeChild(loginFormIframe);
				loginFormIframe = null;
			}
			if(welcomeMessageIframe && typeof welcomeMessageIframe == 'object') {
				document.body.removeChild(welcomeMessageIframe);
				welcomeMessageIframe = null;
			}
		};
	});

	export let appId;
	export let options;
</script>

<svelte:options accessors/>
<main>
	{#if isInitiated}
		{#if (!isLoginFormOpened && !isWidgetOpened && isMobile) || !isMobile}
		<QiscusTriggerBtn 
			on:click={toggleWidget} 
			isMobile={isMobile}
			label={qismoConfig.buttonText} 
			icon={qismoConfig.buttonIcon}>
		</QiscusTriggerBtn>
		{/if}
	{/if}
</main>

<style>
	:global(iframe#qcw-iframe, iframe#qcw-welcome-iframe, iframe#qcw-login-form-iframe) {
		border: 0;
		margin: 0;
		padding: 0;
		position: fixed;
		right: 42px;
		bottom: 77px;
		box-shadow: 0px 15px 25px rgba(189,189,189,0.24);
		border-radius: 8px;
		z-index: 9999;
	}
	:global(iframe#qcw-welcome-iframe) {
		right: 0;
		box-shadow: none;
	}
	.qiscus-widget-container {
		position: fixed;
		bottom: 15px;
		right: 15px;
		max-width: 360px;
		display: flex;
		align-items: flex-end;
		flex-direction: column;
	}

	@media (min-width: 640px) {
		main {
			max-width: none;
		}
	}
</style>